北京青年团契 · 青年基督徒的聚会平台 .hero-media { position: absolute; inset: 0;
} .hero-media img { width: 100%; height: 100%; object-fit: cover; object-position: center 35%; transform: scale(1.03); animation: heroDrift 20s ease-in-out infinite alternate;
} .hero-media::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(13, 27, 42, 0.5) 0%, rgba(13, 27, 42, 0.78) 100%), radial-gradient(ellipse at 50% 15%, rgba(244, 213, 141, 0.14), transparent 50%);
} @keyframes heroDrift { from { transform: scale(1.03); } to { transform: scale(1.07); }
} .hero-content { position: relative; z-index: 2; padding: 0 1.5rem; animation: fadeUp 1s var(--ease) both;
} .hero-brand { font-family: var(--font-serif); font-size: clamp(2.4rem, 6.5vw, 4.2rem); font-weight: 900; line-height: 1.15; color: var(--cream); letter-spacing: 0.06em; margin-bottom: 0.85rem;
} .hero-brand .accent { background: linear-gradient(135deg, var(--gold-300), var(--gold-500)); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
} .hero-tagline { font-family: var(--font-serif); font-size: clamp(0.95rem, 2vw, 1.15rem); color: var(--gold-300); letter-spacing: 0.2em; margin-bottom: 1rem;
} .hero-lead { font-size: 1rem; color: var(--text-light); max-width: 420px; margin: 0 auto 2rem; line-height: 1.8;
} .hero-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap;
} .scroll-hint { position: absolute; bottom: 1.8rem; left: 50%; transform: translateX(-50%); z-index: 2; color: var(--text-muted); font-size: 0.75rem; letter-spacing: 0.12em; animation: float 3s ease-in-out infinite;
} /* —— 关于 + 活动（合一） —— */
.fellowship { padding: 4.5rem 0; background: linear-gradient(180deg, var(--parchment) 0%, var(--cream) 100%);
} .fellowship-layout { display: grid; grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr); gap: 2.5rem; align-items: center; max-width: 1040px; margin: 0 auto;
} .fellowship-poster { border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-md); border: 1px solid rgba(212, 160, 23, 0.15); background: #f5f2ea;
} .fellowship-poster img { width: 100%; height: auto; display: block;
} .fellowship-copy .eyebrow { display: inline-block; font-size: 0.8rem; font-weight: 600; letter-spacing: 0.18em; color: var(--gold-600); margin-bottom: 0.7rem;
} .fellowship-copy h2 { font-family: var(--font-serif); font-size: clamp(1.6rem, 3vw, 2.1rem); color: var(--text-primary); line-height: 1.35; margin-bottom: 1rem;
} .fellowship-copy .lead { color: var(--text-secondary); font-size: 1rem; line-height: 1.9; margin-bottom: 1.2rem;
} .fellowship-meta { display: flex; flex-wrap: wrap; gap: 0.6rem 1.4rem; margin-bottom: 1.6rem; font-size: 0.9rem; color: var(--night-700); font-weight: 600;
} .fellowship-meta span::before { content: "·"; margin-right: 0.55rem; color: var(--gold-500);
} .fellowship-meta span:first-child::before { content: none; margin: 0;
} .activity-chips { display: flex; flex-wrap: wrap; gap: 0.55rem; margin-bottom: 1.6rem;
} .activity-chips span { font-size: 0.86rem; color: var(--text-secondary); padding: 0.4rem 0.85rem; border: 1px solid rgba(212, 160, 23, 0.28); border-radius: var(--radius-full); background: rgba(255, 253, 248, 0.8); letter-spacing: 0.04em;
} .fellowship-motto { font-family: var(--font-serif); font-size: 1.05rem; color: var(--night-700); letter-spacing: 0.06em; padding-top: 1.1rem; border-top: 1px solid rgba(212, 160, 23, 0.22);
} /* —— 入口区 —— */
.entries { padding: 4rem 0 4.5rem; background: var(--parchment-dark);
} .entries-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.2rem; max-width: 1040px; margin: 0 auto;
} .entry { display: block; padding: 1.6rem 1.3rem; background: var(--cream); border: 1px solid rgba(212, 160, 23, 0.12); border-radius: var(--radius-md); transition: transform 0.35s var(--ease), box-shadow 0.35s var(--ease); min-height: 100%;
} .entry:hover { transform: translateY(-5px); box-shadow: var(--shadow-md);
} .entry .icon { font-size: 1.5rem; margin-bottom: 0.7rem;
} .entry h3 { font-family: var(--font-serif); font-size: 1.15rem; color: var(--text-primary); margin-bottom: 0.45rem;
} .entry p { font-size: 0.88rem; color: var(--text-secondary); line-height: 1.65;
} .entry.highlight { background: linear-gradient(160deg, var(--night-800), var(--night-700)); border-color: rgba(244, 213, 141, 0.25);
} .entry.highlight h3,
.entry.highlight p { color: var(--cream);
} .entry.highlight p { color: var(--text-light);
} /* —— 邀请条 —— */
.invite-bar { padding: 2.8rem 1.5rem; background: var(--night-900); text-align: center;
} .invite-bar p { font-family: var(--font-serif); color: var(--cream); font-size: clamp(1.1rem, 2.5vw, 1.4rem); margin-bottom: 1.2rem; letter-spacing: 0.04em;
} @media (max-width: 900px) { .fellowship-layout { grid-template-columns: 1fr; gap: 2rem; } .fellowship-poster { max-width: 420px; margin: 0 auto; } .entries-grid { grid-template-columns: repeat(2, 1fr); }
} @media (max-width: 520px) { .entries-grid { grid-template-columns: 1fr; } .hero { min-height: 82vh; }
