有声频道 · 北京青年团契 .page-hero { position: relative; padding: 9rem 2rem 4.5rem; text-align: center; overflow: hidden; background: radial-gradient(ellipse at 20% 10%, rgba(244, 213, 141, 0.18), transparent 42%), radial-gradient(ellipse at 80% 0%, rgba(74, 122, 181, 0.22), transparent 40%), radial-gradient(ellipse at 50% 0%, var(--night-700) 0%, var(--night-900) 72%); color: var(--cream);
} .page-hero::before { content: ""; position: absolute; inset: 0; background-image: radial-gradient(1.5px 1.5px at 15% 40%, rgba(244, 213, 141, 0.5), transparent), radial-gradient(1px 1px at 50% 25%, rgba(255, 255, 255, 0.4), transparent), radial-gradient(1.5px 1.5px at 80% 50%, rgba(244, 213, 141, 0.3), transparent); pointer-events: none;
} .page-hero-content { position: relative; z-index: 1; max-width: 760px; margin: 0 auto; animation: fadeUp 1s var(--ease) both;
} .breadcrumb { display: flex; align-items: center; justify-content: center; gap: 0.6rem; font-size: 0.85rem; color: var(--text-muted); margin-bottom: 1.5rem;
} .breadcrumb a { color: var(--text-light); }
.breadcrumb a:hover { color: var(--gold-300); }
.breadcrumb .sep { color: var(--gold-600); } .page-hero-eyebrow { display: inline-block; font-size: 0.82rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--gold-300); margin-bottom: 1rem;
} .page-hero h1 { font-family: var(--font-serif); font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 900; line-height: 1.2; margin-bottom: 1rem;
} .page-hero h1 .accent { background: linear-gradient(135deg, var(--gold-300), var(--gold-500)); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
} .page-hero-desc { color: var(--text-light); font-size: 1.05rem; line-height: 1.85; max-width: 560px; margin: 0 auto;
} .module-wrap { max-width: 1100px; margin: -1.6rem auto 0; padding: 0 2rem; position: relative; z-index: 3;
} .module-tabs { display: flex; flex-wrap: wrap; gap: 0.65rem; justify-content: center; padding: 0.55rem; background: rgba(255, 253, 248, 0.92); backdrop-filter: blur(10px); border: 1px solid rgba(212, 160, 23, 0.2); border-radius: var(--radius-full); box-shadow: var(--shadow-md); width: fit-content; max-width: 100%; margin: 0 auto 2rem;
} .module-tab { border: none; cursor: pointer; font-family: var(--font-sans); font-size: 0.95rem; font-weight: 600; padding: 0.7rem 1.35rem; border-radius: var(--radius-full); color: var(--text-secondary); background: transparent; transition: all 0.3s var(--ease);
} .module-tab:hover { color: var(--night-700); }
.module-tab.active { color: var(--night-900); background: linear-gradient(135deg, var(--gold-400), var(--gold-500)); box-shadow: var(--shadow-gold);
} .module-panel { display: none; }
.module-panel.active { display: block; animation: fadeUp 0.55s var(--ease) both; } .intro-card { background: var(--cream); border-radius: var(--radius-lg); padding: 1.8rem 2rem; box-shadow: var(--shadow-sm); border: 1px solid rgba(212, 160, 23, 0.16); border-left: 4px solid var(--gold-500); color: var(--text-secondary); white-space: pre-line; max-width: 820px; margin: 0 auto 2rem;
} .intro-card blockquote { margin: 1rem 0; padding-left: 1rem; border-left: 3px solid rgba(212, 160, 23, 0.45); color: var(--text-primary); font-family: var(--font-serif);
} .playlist-section { padding: 0 0 2rem; } .track-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1.1rem;
} .track-card { background: var(--cream); border-radius: var(--radius-md); padding: 1.2rem 1.25rem 1.15rem; border: 1px solid rgba(212, 160, 23, 0.14); box-shadow: var(--shadow-sm); transition: transform 0.3s var(--ease), box-shadow 0.3s var(--ease), border-color 0.3s var(--ease); cursor: pointer; -webkit-user-select: none; user-select: none;
} .track-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); border-color: rgba(212, 160, 23, 0.35);
} .track-card.is-active { border-color: var(--gold-500); box-shadow: var(--shadow-gold); background: linear-gradient(165deg, #fffdf8, #f7efd8);
} .track-card.is-loading { opacity: 0.72; pointer-events: none; } .track-top { display: flex; gap: 0.95rem; align-items: flex-start; } .track-play { flex: 0 0 46px; width: 46px; height: 46px; border-radius: 50%; border: none; cursor: pointer; display: grid; place-items: center; background: linear-gradient(135deg, var(--gold-400), var(--gold-500)); color: var(--night-900); box-shadow: var(--shadow-gold);
} .track-play svg { width: 18px; height: 18px; fill: currentColor; }
.track-meta { flex: 1; min-width: 0; }
.track-index { font-size: 0.75rem; letter-spacing: 0.1em; color: var(--gold-600); font-weight: 700; margin-bottom: 0.25rem;
}
.track-title { font-family: var(--font-serif); font-size: 1.08rem; color: var(--text-primary); line-height: 1.4; margin-bottom: 0.25rem;
}
.track-sub { font-size: 0.88rem; color: var(--text-muted); } .track-progress { margin-top: 0.95rem; height: 4px; border-radius: 999px; background: rgba(13, 27, 42, 0.08); overflow: hidden;
} .track-progress > span { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold-400), var(--gold-500)); border-radius: inherit;
} /* 灵性模块 */
.soul-shell { max-width: 720px; margin: 0 auto; background: var(--cream); border-radius: var(--radius-lg); box-shadow: var(--shadow-lg); border: 1px solid rgba(212, 160, 23, 0.18); overflow: hidden; -webkit-user-select: none; user-select: none;
} .soul-art { padding: 2.2rem 1.5rem 1.5rem; text-align: center; background: radial-gradient(circle at 50% 20%, rgba(244, 213, 141, 0.22), transparent 55%), linear-gradient(160deg, #13243a 0%, #1b3358 55%, #234070 100%); color: var(--cream);
} .disc { width: 132px; height: 132px; margin: 0 auto 1.1rem; border-radius: 50%; background: radial-gradient(circle at 50% 50%, #f4d58d 0 10%, transparent 11%), conic-gradient(from 0deg, #0d1b2a, #234070, #0d1b2a, #1b3358, #0d1b2a); border: 4px solid rgba(244, 213, 141, 0.45); box-shadow: 0 12px 36px rgba(0, 0, 0, 0.35); position: relative;
} .disc.spinning { animation: spinDisc 8s linear infinite; }
@keyframes spinDisc { to { transform: rotate(360deg); } } .disc::after { content: ""; position: absolute; inset: 28%; border-radius: 50%; background: rgba(13, 27, 42, 0.85); border: 2px solid rgba(244, 213, 141, 0.35);
} .soul-art .badge { display: inline-block; padding: 0.25rem 0.8rem; border-radius: 999px; font-size: 0.75rem; letter-spacing: 0.08em; color: var(--night-900); background: linear-gradient(135deg, var(--gold-300), var(--gold-500)); margin-bottom: 0.7rem;
} .soul-art h3 { font-family: var(--font-serif); font-size: 1.5rem; margin-bottom: 0.35rem;
} .soul-art p { color: rgba(245, 239, 226, 0.8); font-size: 0.95rem; } .soul-controls { padding: 1.5rem 1.4rem 1.6rem; } .seek-row { display: grid; grid-template-columns: auto 1fr auto; gap: 0.75rem; align-items: center; margin-bottom: 1.1rem;
} .seek-row span { font-size: 0.8rem; color: var(--text-muted); font-variant-numeric: tabular-nums; min-width: 2.4rem;
} .seek { appearance: none; width: 100%; height: 6px; border-radius: 999px; background: rgba(13, 27, 42, 0.1); outline: none; cursor: pointer;
} .seek::-webkit-slider-thumb { appearance: none; width: 16px; height: 16px; border-radius: 50%; background: linear-gradient(135deg, var(--gold-400), var(--gold-500)); box-shadow: var(--shadow-gold); cursor: pointer;
} .control-row { display: flex; align-items: center; justify-content: center; gap: 1rem;
} .ctrl-btn { width: 50px; height: 50px; border-radius: 50%; border: 1px solid rgba(212, 160, 23, 0.25); background: var(--parchment); color: var(--night-700); cursor: pointer; display: grid; place-items: center;
} .ctrl-btn svg { width: 18px; height: 18px; fill: currentColor; }
.ctrl-btn.main { width: 64px; height: 64px; border: none; background: linear-gradient(135deg, var(--gold-400), var(--gold-500)); color: var(--night-900); box-shadow: var(--shadow-gold);
}
.ctrl-btn.main svg { width: 24px; height: 24px; }
.ctrl-btn:disabled { opacity: 0.55; cursor: wait; } .status-line { margin-top: 0.9rem; text-align: center; font-size: 0.88rem; color: var(--text-muted); min-height: 1.2em;
} .soul-tips { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 0.85rem; max-width: 720px; margin: 1.4rem auto 0;
} .soul-tip { padding: 1rem 1.1rem; border-radius: var(--radius-md); background: rgba(27, 51, 88, 0.05); border: 1px solid rgba(27, 51, 88, 0.08);
} .soul-tip strong { display: block; color: var(--night-700); font-size: 0.9rem; margin-bottom: 0.25rem;
} .soul-tip span { color: var(--text-secondary); font-size: 0.92rem; line-height: 1.55;
} .soul-verse { max-width: 720px; margin: 1.5rem auto 0; text-align: center; padding: 1.5rem 1.2rem; border-radius: var(--radius-md); background: linear-gradient(180deg, rgba(244, 213, 141, 0.12), rgba(250, 246, 238, 0.95)); border: 1px solid rgba(212, 160, 23, 0.22);
} .soul-verse p { font-family: var(--font-serif); font-size: 1.15rem; color: var(--night-700); margin-bottom: 0.45rem;
} .soul-verse cite { color: var(--gold-600); font-style: normal; font-size: 0.9rem;
} .continue-box { max-width: 820px; margin: 2.5rem auto 0; padding: 1.4rem 1.6rem; border-radius: var(--radius-md); background: linear-gradient(180deg, #fffdf8, #f7f1e4); border: 1px solid rgba(212, 160, 23, 0.2);
} .continue-box .links { display: flex; flex-wrap: wrap; gap: 0.8rem 1.4rem; margin-top: 0.7rem;
} .continue-box a { color: var(--night-600); font-weight: 600; }
.continue-box a:hover { color: var(--gold-600); } .now-playing { position: fixed; left: 0; right: 0; bottom: 0; z-index: 1200; background: rgba(13, 27, 42, 0.96); backdrop-filter: blur(14px); border-top: 1px solid rgba(244, 213, 141, 0.2); padding: 0.85rem 1.2rem; display: none; align-items: center; gap: 1rem; color: var(--cream); box-shadow: 0 -10px 30px rgba(13, 27, 42, 0.25); -webkit-user-select: none; user-select: none;
} .now-playing.visible { display: flex; } .np-btn { flex: 0 0 44px; width: 44px; height: 44px; border-radius: 50%; border: none; cursor: pointer; background: linear-gradient(135deg, var(--gold-400), var(--gold-500)); color: var(--night-900); display: grid; place-items: center;
} .np-btn svg { width: 18px; height: 18px; fill: currentColor; }
.np-info { flex: 1; min-width: 0; }
.np-label { font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--gold-300); margin-bottom: 0.15rem;
}
.np-title { font-family: var(--font-serif); font-size: 0.98rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.np-time { font-size: 0.82rem; color: var(--text-light); font-variant-numeric: tabular-nums; white-space: nowrap;
} .np-seek { position: absolute; left: 0; right: 0; top: 0; height: 3px; appearance: none; background: transparent; cursor: pointer;
} .np-seek::-webkit-slider-runnable-track { height: 3px; background: rgba(255,255,255,0.15);
} .np-seek::-webkit-slider-thumb { appearance: none; width: 12px; height: 12px; margin-top: -4.5px; border-radius: 50%; background: var(--gold-400);
} @media (max-width: 700px) { .page-hero { padding: 7.5rem 1.2rem 3.5rem; } .module-wrap { padding: 0 1.2rem; } .module-tabs { border-radius: 16px; } .intro-card { padding: 1.35rem 1.2rem; } .np-time { display: none; }
